<script setup lang="ts">
import type { Taxon, ContentType } from '~/types'
import { sections, sectionOf } from '~/utils/site'
import { NModal, useMessage } from 'naive-ui'
definePageMeta({ layout: 'admin' }); useSeoMeta({ title: '分类与标签' })
const api = useApi(), message = useMessage(), confirm = useConfirm()
const { data, error, refresh } = await useFetch<{ categories: Taxon[]; tags: Taxon[] }>('/api/admin/taxonomy')
const kind = ref<'categories' | 'tags'>('categories'), show = ref(false), busy = ref(false), editing = ref<Taxon | null>(null)
const form = reactive({ name: '', slug: '', type: 'article' as ContentType, sortOrder: 0 })
function open(which: typeof kind.value, item?: Taxon) { kind.value = which; editing.value = item || null; Object.assign(form, { name: item?.name || '', slug: item?.slug || '', type: item?.contentType || 'article', sortOrder: item?.sortOrder || 0 }); show.value = true }
async function save() {
  busy.value = true
  try { await api(`/api/admin/taxonomy/${kind.value}${editing.value ? `/${editing.value.id}` : ''}`, { method: editing.value ? 'PUT' : 'POST', body: form }); show.value = false; message.success('已保存'); await refresh() } catch (e) { message.error(errorText(e)) } finally { busy.value = false }
}
async function remove(which: typeof kind.value, item: Taxon) { if (!await confirm('删除分类或标签？', `确认删除「${item.name}」？已被历史版本引用的词汇不能删除。`)) return; try { await api(`/api/admin/taxonomy/${which}/${item.id}`, { method: 'DELETE' }); await refresh(); message.success('已删除') } catch (e) { message.error(errorText(e)) } }
</script>
<template><div><AdminPageHead title="分类与标签" subtitle="让零散的记录，有清晰的脉络。"><button @click="open('tags')">＋ 新建标签</button><button class="primary" @click="open('categories')">＋ 新建分类</button></AdminPageHead><p v-if="error" class="form-error" role="alert">加载失败。<button @click="refresh()">重试</button></p><div class="taxonomy-grid"><section class="studio-panel"><h2>内容分类</h2><div class="table-scroll"><table class="admin-table"><thead><tr><th>名称</th><th>栏目</th><th>已发布</th><th>操作</th></tr></thead><tbody><tr v-for="item in data?.categories" :key="item.id"><td>{{ item.name }}<small>{{ item.slug }}</small></td><td>{{ sectionOf(item.contentType!).label }}</td><td>{{ item.count }}</td><td class="row-actions"><button @click="open('categories', item)">编辑</button><button @click="remove('categories', item)" class="danger">删除</button></td></tr></tbody></table></div><p v-if="!data?.categories.length" class="admin-empty">还没有分类。</p></section><section class="studio-panel"><h2>全站标签</h2><div v-for="item in data?.tags" :key="item.id" class="tag-manage-row"><span class="tag">{{ item.name }}</span><small>{{ item.count }} 条公开内容</small><button @click="open('tags', item)">编辑</button><button @click="remove('tags', item)" class="danger">删除</button></div><p v-if="!data?.tags.length" class="admin-empty">还没有标签。</p></section></div><NModal v-model:show="show" preset="card" :title="`${editing ? '编辑' : '新建'}${kind === 'categories' ? '分类' : '标签'}`" style="width:min(500px,calc(100% - 30px))"><form @submit.prevent="save"><div class="field"><label for="tax-name">名称</label><input id="tax-name" v-model="form.name" required maxlength="60"></div><div class="field"><label for="tax-slug">地址标识</label><input id="tax-slug" v-model="form.slug" :disabled="!!editing" required maxlength="80" pattern="[a-z0-9]+(-[a-z0-9]+)*"></div><div v-if="kind === 'categories'" class="field"><label for="tax-type">所属栏目</label><select id="tax-type" v-model="form.type" :disabled="!!editing"><option v-for="s in sections" :key="s.type" :value="s.type">{{ s.label }}</option></select><label for="tax-sort">排序</label><input id="tax-sort" v-model.number="form.sortOrder" type="number" min="0"></div><button class="primary" :disabled="busy">保存</button></form></NModal></div></template>
